<template>
  <div class="progress-container">
    <h2 class="progress-title">Training Progress</h2>
    <div class="progress-bar-wrapper">
      <div class="progress-bar" :style="{ width: progress + '%', background: barColor }">
        <span class="progress-text">{{ progress }}%</span>
      </div>
    </div>
    <div class="log-section">
      <h3>Training Log</h3>
      <div class="log-box">
        <div v-for="(entry, index) in logEntries" :key="index" class="log-entry" :class="{ done: entry.done }">
          {{ entry.message }}
        </div>
      </div>
    </div>
    <div v-if="progress >= 100" class="button-section">
      <button @click="goToShowModel" class="complete-btn">View Results</button>
    </div>
  </div>
</template>
<script>
import { defineComponent } from 'vue';
import io from 'socket.io-client';
import { apiConfig } from '@/config/apiConfig';
import { sanitizeAndParseResponse } from '@/config/apiConfig';

export default defineComponent({
  name: 'ProgressBar',
//   props: {
//     config: {
//       type: Object,
//       required: true,
//     },
//   },
  data() {
    return {
      progress: 0,
      logEntries: [],
      totalModels: 0,
      completedModels: 0,
      socket: null,
    };
  },
  computed: {
    isDarkMode() {
      return document.documentElement.getAttribute('data-theme') === 'dark';
    },
    barColor() {
      return this.isDarkMode
        ? `linear-gradient(45deg, #00c6fb, #005bea)`
        : `linear-gradient(45deg, #ff6b6b, #ee5253)`;
    },
  },
  mounted() {
    this.initializeWebSocket();
    this.startTraining();
  },
  beforeUnmount() {
    if (this.socket) {
      this.socket.disconnect();
    }
  },
  methods: {
    initializeWebSocket() {
      this.socket = io(apiConfig.baseUrl());
      this.socket.on('connect', () => {
        console.log('WebSocket connected:', this.socket.id);
      });

      this.socket.on('progress', (data) => {
        console.log('Progress update:', data);
        this.logEntries.push({ message: data.message, done: data.done, timestamp: data.timestamp });
        if (data.done) this.completedModels++;
        this.updateProgress();
      });

      this.socket.on('disconnect', () => {
        console.log('WebSocket disconnected');
      });

      this.socket.on('response', (data) => {
        console.log('Training complete response:', data);
        // No automatic navigation here; button will handle it
      });
    },
    async startTraining() {
      if (!this.config || !this.config.models) {
        console.error('Training config is undefined or missing models:', this.config);
        alert('Invalid training configuration. Please try again.');
        this.$router.push({ name: 'SelectModel' });
        return;
      }
      this.totalModels = this.config.models.length;

      try {
        const response = await fetch(apiConfig.endpoints.mlPredictEndpoint(), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(this.config),
        });
        if (!response.ok) throw new Error('Training request failed');
        const data = sanitizeAndParseResponse(await response.text());
        if (data) {
          this.$root.setApiData(data); // Store performance data
        }
      } catch (error) {
        console.error('Error starting training:', error);
        alert('Failed to start training. Check console for details.');
      }
    },
    updateProgress() {
      if (this.totalModels > 0) {
        this.progress = (this.completedModels / this.totalModels) * 100;
      }
    },
    goToShowModel() {
      this.$router.push({ name: 'ShowModel' });
    },
  },
});
</script>

<style scoped>
.progress-container {
  padding: 40px;
  max-width: 800px;
  margin: 0 auto;
  background: var(--card-bg);
  border-radius: 15px;
  box-shadow: var(--shadow);
  animation: fadeIn 1s ease-in-out;
  position: relative;
  overflow: hidden;
}

.progress-title {
  color: var(--primary-color);
  text-align: center;
  font-size: 2rem;
  margin-bottom: 20px;
  text-transform: uppercase;
  letter-spacing: 2px;
}

.progress-bar-wrapper {
  width: 100%;
  background: var(--bg-color);
  border-radius: 10px;
  overflow: hidden;
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.1);
}

.progress-bar {
  height: 40px;
  background: linear-gradient(45deg, #ff6b6b, #ee5253);
  text-align: center;
  color: var(--bg-color);
  font-weight: bold;
  transition: width 0.5s ease, background 0.3s ease;
  position: relative;
  animation: pulse 2s infinite;
}

.progress-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 1.1rem;
}

.log-section {
  margin-top: 20px;
}

.log-section h3 {
  color: var(--primary-color);
  margin-bottom: 10px;
}

.log-box {
  background: var(--card-bg);
  padding: 15px;
  border-radius: 10px;
  max-height: 200px;
  overflow-y: auto;
  border: 1px solid var(--secondary-color);
}

.log-entry {
  margin-bottom: 8px;
  padding: 5px;
  border-radius: 5px;
  transition: background 0.3s ease;
}

.log-entry.done {
  background: rgba(0, 255, 0, 0.1);
  color: var(--text-color);
  font-weight: bold;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.02); }
  100% { transform: scale(1); }
}
</style>