<template>
  <div id="app">
    <div class="theme-switch-container">
      <label class="theme-slider" for="theme-toggle">
        <input type="checkbox" id="theme-toggle" v-model="isDarkMode" @change="toggleDarkMode" />
        <div class="slider round"></div>
      </label>
      <!-- <span class="theme-status">{{ isDarkMode ? 'Dark' : 'Light' }} Mode</span> Debug indicator -->
    </div>
    <RouterView />
    <!-- <RouterView :api-data="apiData" @clear-api-data="clearApiData" /> -->
  </div>
</template>

<script>
import { ref, provide } from 'vue';
import './assets/styles.css';
export default {
  name: 'App',
  setup() {
    const apiData = ref(null);

    const setApiData = (data) => {
      console.log('Setting apiData in App.vue:', data);
      apiData.value = data;
    };

    const clearApiData = () => {
      console.log('Clearing apiData in App.vue');
      apiData.value = null;
    };

    provide('apiData', apiData);
    provide('setApiData', setApiData);
    provide('clearApiData', clearApiData);

    return {
      apiData,
      clearApiData,
    };
  },
  data() {
    return {
      isDarkMode: false, // Start in light mode
    };
  },
  methods: {
    toggleDarkMode() {
      this.isDarkMode == !this.isDarkMode;
      console.log('Toggling to:', this.isDarkMode ? 'dark' : 'light');
      document.documentElement.setAttribute('data-theme', this.isDarkMode ? 'dark' : 'light');
    },
  },
  mounted() {
    const savedTheme = localStorage.getItem('theme');
    console.log('Saved theme from localStorage:', savedTheme);
    this.isDarkMode = savedTheme === 'dark' ? true : false; // Explicitly handle the state
    console.log('Initial isDarkMode set to:', this.isDarkMode ? 'dark' : 'light');
    document.documentElement.setAttribute('data-theme', this.isDarkMode ? 'dark' : 'light');
  },
  watch: {
    isDarkMode(newValue) {
      console.log('Theme updated to:', newValue ? 'dark' : 'light');
      localStorage.setItem('theme', newValue ? 'dark' : 'light');
      document.documentElement.setAttribute('data-theme', newValue ? 'dark' : 'light');
    },
  },
};
</script>

<style>
#app {
  font-family: 'Avenir', Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-align: center;
  color: var(--text-color);
  margin-top: 0px;
  
  min-height: 130vh;
  background: var(--bg-color);
  position: relative;
  transition: all 0.3s ease; /* Smooth transition */
}

.theme-switch-container {
  position: fixed;
  top: 20px;
  right: 10px;
  display: flex;
  align-items: center;
}

.theme-slider {
  display: inline-block;
  height: 24px;
  position: relative;
  width: 40px;
}

.theme-slider input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  background-color: var(--text-color);
  bottom: 0;
  cursor: pointer;
  left: 0;
  position: absolute;
  right: 0;
  top: 0;
  transition: 0.4s;
  border-radius: 34px;
}

.slider:before {
  background-color: #afd2dd;
  bottom: 2px;
  content: "";
  height: 20px;
  left: 2px;
  position: absolute;
  transition: 0.4s;
  width: 20px;
  border-radius: 50%;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
}

.theme-slider input:checked + .slider {
  background-color: #fdfffb;
}

.theme-slider input:checked + .slider:before {
  transform: translateX(17px);
}

.theme-slider input:focus + .slider {
  box-shadow: 0 0 5px var(--secondary-color);
}

.theme-status {
  margin-left: 10px;
  color: var(--text-color);
  font-size: 14px;
}
</style>