  export const sanitizeAndParseResponse = (responseText) => {
    // Replace NaN with null to make it JSON-compatible
    const sanitizedText = responseText.replace(/\bNaN\b/g, 'null');
    try {
      return JSON.parse(sanitizedText);
    } catch (error) {
      console.error('Error parsing sanitized response:', error);
      return null; // Return null if parsing fails
    }
  };

    